INK = '#0f172a'
GRAY = '#64748b'
FONT = 'Helvetica, Arial, sans-serif'
MONO = 'Courier New, Courier, monospace'
FLOOR = 20

class Svg:

    def __init__(self, w, h):
        self.w, self.h, self.parts = (w, h, [])

    def add(self, s):
        self.parts.append(s)

    def save(self, name):
        markers = ''.join((f'<marker id="a{k}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="{col}"/></marker>' for k, col in (('blue', ROLE['model'][1]), ('violet', ROLE['sys'][1]), ('amber', ROLE['tool'][1]), ('green', ROLE['memory'][1]), ('red', ROLE['fault'][1]), ('gray', GRAY))))
        svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {self.w} {self.h}" width="{self.w}" height="{self.h}" font-family="{FONT}"><defs>{markers}<pattern id="hatch" width="10" height="10" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="10" stroke="#cbd5e1" stroke-width="4"/></pattern></defs><rect x="0" y="0" width="{self.w}" height="{self.h}" fill="white"/>' + ''.join(self.parts) + '</svg>'
        (OUT / f'{name}.svg').write_text(svg)

    def rect(self, x, y, w, h, role='struct', dash=False, rx=8, sw=2, fill=None):
        f, s, _ = ROLE[role]
        d = ' stroke-dasharray="7 5"' if dash else ''
        self.add(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill or f}" stroke="{s}" stroke-width="{sw}"{d}/>')

    def text(self, x, y, s, fs=22, color=INK, anchor='middle', weight='normal', mono=False, italic=False):
        fs = max(fs, FLOOR)
        fam = f' font-family="{MONO}"' if mono else ''
        it = ' font-style="italic"' if italic else ''
        s = s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
        self.add(f'<text x="{x}" y="{y}" font-size="{fs}" fill="{color}" text-anchor="{anchor}" font-weight="{weight}"{fam}{it}>{s}</text>')

    def box(self, x, y, w, h, role, title, sub=None, fs=22, sfs=19, dash=False, mono_sub=False, mono_title=False):
        self.rect(x, y, w, h, role, dash=dash)
        _, _, tc = ROLE[role]
        if sub:
            self.text(x + w / 2, y + h / 2 - 4, title, fs, INK, weight='bold', mono=mono_title)
            self.text(x + w / 2, y + h / 2 + sfs + 2, sub, sfs, tc, mono=mono_sub)
        else:
            self.text(x + w / 2, y + h / 2 + fs * 0.35, title, fs, INK, weight='bold', mono=mono_title)

    def arrow(self, x1, y1, x2, y2, color='gray', dash=False, sw=2.5, path=None):
        col = {'blue': ROLE['model'][1], 'violet': ROLE['sys'][1], 'amber': ROLE['tool'][1], 'green': ROLE['memory'][1], 'red': ROLE['fault'][1], 'gray': GRAY}[color]
        d = ' stroke-dasharray="8 6"' if dash else ''
        geom = path or f'M{x1},{y1} L{x2},{y2}'
        self.add(f'<path d="{geom}" fill="none" stroke="{col}" stroke-width="{sw}"{d} marker-end="url(#a{color})"/>')

    def line(self, x1, y1, x2, y2, color=GRAY, sw=2, dash=False):
        d = ' stroke-dasharray="7 5"' if dash else ''
        self.add(f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-width="{sw}"{d}/>')

    def cross(self, x, y, r=11, color=None):
        col = color or ROLE['fault'][1]
        self.add(f'<path d="M{x - r},{y - r} L{x + r},{y + r} M{x - r},{y + r} L{x + r},{y - r}" stroke="{col}" stroke-width="5"/>')

    def dot(self, x, y, r=12, color=None):
        self.add(f'''<circle cx="{x}" cy="{y}" r="{r}" fill="{color or ROLE['sys'][1]}"/>''')

