def dup_plot():
    rows = [{'n': 20000, 'p_req': 0.02, 'p_rep': 0.02, 'dedup': False, 'timeouts': 780, 'duplicates': 361, 'executed_ops': 19990, 'predicted': 384.16, 'pred_timeouts': 792.0}, {'n': 20000, 'p_req': 0.02, 'p_rep': 0.01, 'dedup': False, 'timeouts': 582, 'duplicates': 171, 'executed_ops': 19990, 'predicted': 192.08, 'pred_timeouts': 596.0}, {'n': 20000, 'p_req': 0.02, 'p_rep': 0.04, 'dedup': False, 'timeouts': 1193, 'duplicates': 762, 'executed_ops': 19990, 'predicted': 768.32, 'pred_timeouts': 1184.0}, {'n': 20000, 'p_req': 0.02, 'p_rep': 0.02, 'dedup': True, 'timeouts': 780, 'duplicates': 0, 'executed_ops': 19990, 'predicted': 0.0, 'pred_timeouts': 792.0}]
    order = sorted((r for r in rows if not r['dedup']), key=lambda r: r['p_rep']) + [r for r in rows if r['dedup']]
    labels = [f"{r['p_rep']:.0%}" + (' +\ndedup' if r['dedup'] else '') for r in order]
    fig, ax = plt.subplots(figsize=(4.2, 2.0))
    x = np.arange(len(order))
    pred = [r['predicted'] for r in order]
    meas = [r['duplicates'] for r in order]
    ax.bar(x - 0.19, pred, 0.36, color=C['neutral_l'], edgecolor=C['neutral'], label='formula')
    ax.bar(x + 0.19, meas, 0.36, color=[C['danger']] * 3 + [C['data']])
    for xi, p, m in zip(x, pred, meas):
        if p:
            ax.text(xi - 0.21, p + 15, f'{p:.0f}', ha='right', fontsize=10, color=C['neutral'])
        ax.text(xi + 0.21, m + 15, f'{m}', ha='left', fontsize=11, fontweight='bold', color=C['data'] if m == 0 else C['danger'])
    ax.set_xticks(x)
    ax.set_xticklabels(labels, fontsize=12)
    ax.set_xlabel('Reply loss (request loss 2%)')
    ax.set_ylabel('Duplicate restarts\nper 20,000 ops')
    ax.set_ylim(0, 1100)
    ax.text(-0.45, 990, 'gray = formula, red = measured', fontsize=11, color=C['text'])
    sp.save(fig, OUT / 'dup_plot.svg')

