def job_states():
    s = Svg(620, 470)
    s.box(10, 10, 270, 90, 'tool', 'accepted', 'queued (202)', fs=26, sfs=22)
    s.arrow(145, 100, 145, 140, 'amber')
    s.box(10, 142, 270, 90, 'tool', 'running', 'last seen at t', fs=26, sfs=22)
    s.arrow(280, 165, 338, 80, 'green')
    s.box(340, 10, 270, 90, 'memory', 'completed', 'result + scope', fs=26, sfs=22)
    s.arrow(280, 200, 338, 260, 'red')
    s.box(340, 230, 270, 90, 'fault', 'failed', 'diagnostic', fs=26, sfs=22)
    s.arrow(145, 232, 145, 290, 'gray', dash=True)
    s.box(10, 292, 270, 96, 'struct', 'unavailable', 'last observed running', fs=26, sfs=21, dash=True)
    s.text(10, 425, 'unavailable is no failure; no rollback,', 22, ROLE['fault'][2], anchor='start', weight='bold')
    s.text(10, 455, 'the runtime keeps watching', 22, GRAY, anchor='start')
    s.save('job_states')

def poll_plot():
    fig, ax = plt.subplots(figsize=(3.9, 2.0))
    ivs = [5, 10, 20, 30, 60]
    costs = [0.87639072, 0.43076832, 0.20795712, 0.13368672, 0.05941632]
    ax.plot(ivs, costs, '-o', color=C['compute'], lw=2.5, ms=7)
    for i, c_ in zip(ivs, costs):
        ax.text(i + 1.2, c_ + 0.03, f'${c_:.2f}', fontsize=11, color=C['compute'], fontweight='bold')
    runtime = 10
    ax.plot([runtime], [0], 's', color=C['data'], ms=10, clip_on=False)
    ax.annotate(f'runtime polls every {runtime:.0f} s: $0', xy=(10.5, 0.01), xytext=(24, 0.45), fontsize=11, color=C['data'], fontweight='bold', arrowprops=dict(arrowstyle='->', color=C['data']))
    ax.text(22, 0.8, 'model polls: halving the delay\ndoubles the cost', fontsize=11, color=C['compute'])
    ax.set_xlabel('Poll interval = worst detection delay (s)')
    ax.set_ylabel('Extra $ per 300 s job')
    ax.set_xlim(0, 66)
    ax.set_ylim(0, 1.0)
    sp.save(fig, OUT / 'poll_plot.svg')

def catalog():
    rows = [('All 131 GitHub tools', 28986.0, 'danger', '28,986 (measured)'), ('50 tools × 300', 15000.0, 'neutral', '15,000'), ('6 selected + 400', 2200.0, 'data', '2,200')]
    for k in range(1, 4):
        sp.hbars(str(OUT / f'catalog_step{k}.svg'), rows, '', log=False, step=k, size=(5.8, 1.45), xlabel='Descriptor tokens on every model call')

def deep_shallow():
    s = Svg(600, 430)
    s.text(10, 30, 'Shallow: 4 model calls', 22, INK, anchor='start', weight='bold')
    names = ['open', 'seek', 'write', 'close']
    for i, n in enumerate(names):
        x = 10 + i * 148
        s.box(x, 46, 128, 56, 'model', f'call {i + 1}', fs=20)
        s.box(x, 132, 128, 52, 'tool', n, fs=20, mono_title=True)
        s.arrow(x + 50, 102, x + 50, 130, 'blue')
        s.arrow(x + 80, 132, x + 80, 104, 'green')
        if i < 3:
            s.arrow(x + 128, 74, x + 146, 74, 'gray')
    s.line(10, 214, 590, 214, '#cbd5e1', 2)
