        s.line(320, 271, 370, 271, '#0284c7', 2)
        s.line(345, 246, 345, 296, '#0284c7', 2)
        s.text(300, 352, 'proposed click (640, 420)', 23, ROLE['model'][2])
        s.text(300, 384, 'from frame f_12', 22, GRAY)
